function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const O = '#0d0a08', P1 = '#2a2620', P2 = '#4a443c', P3 = '#6a6358';
  const M1 = '#c45cff', M2 = '#f0e0ff';
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };
  px(0, 0, 64, 64, P1);
  for (let y = 12; y < 52; y++) {
    for (let x = 12; x < 52; x++) {
      const dx = x - 32, dy = y - 32;
      const d2 = dx * dx + dy * dy;
      if (d2 <= 18 * 18) px(x, y, 1, 1, M1);
      else if (d2 <= 22 * 22) px(x, y, 1, 1, M2);
    }
  }
  px(8, 8, 48, 6, P2);
  px(8, 8, 6, 48, P2);
  px(50, 8, 6, 48, P2);
  px(8, 50, 48, 6, P2);
  px(8, 8, 48, 2, P3);
  px(8, 8, 2, 48, P3);
  px(54, 8, 2, 48, P1);
  px(8, 54, 48, 2, P1);
  px(28, 4, 8, 10, P2);
  px(29, 2, 6, 8, P3);
  px(28, 4, 8, 2, O);
  px(28, 4, 2, 10, O);
  px(34, 4, 2, 10, O);
  for (let a = 0; a < 360; a += 2) {
    const rad = a * Math.PI / 180;
    const x = 32 + Math.round(Math.cos(rad) * 20);
    const y = 32 + Math.round(Math.sin(rad) * 20);
    if (x >= 0 && x < 64 && y >= 0 && y < 64) px(x, y, 1, 1, O);
  }
  px(30, 28, 4, 4, M2);
}
